from bloomerp.models.communication.calendar.calendar_event import CalendarEvent
from django.http import HttpResponse
from django.utils import timezone
from bloomerp.permissions.definition import RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestCalendarEventCancelView(InboxCalendarFixtures, BloomerpDetailViewTestCase):
    """Tests class `CalendarEventCancelView` from `bloomerp/views/communication/calendar/cancel.py`."""

    view_name = 'cancel'
    model = CalendarEvent

    def extendedSetup(self) -> None:
        """Prepare a local event with a guest and an unprivileged staff calendar owner."""
        self.prepare_calendar()
        self.timed.organizing_inbox = self.source
        self.timed.save()
        self.timed.participants.create(email="guest@example.com")

    def create_test_object(self) -> CalendarEvent:
        """Resolve cancellation against the existing local event."""
        return self.timed

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        return [
            RequestScenario(name="Cancellation is POST-only", user=self.actor,
                expected=ExpectedResult(status_code=405)),
            RequestScenario(name="Cancel ignores unfinished composer edits", user=self.actor,
                method="POST", data={"title": "", "attendees": "unfinished"},
                headers={"HX-Request": "true", "HX-Target": "calendar-event-create-form"},
                expected=ExpectedResult(status_code=204, response_validators=self.event_cancelled)),
            RequestScenario(name="Staff event editors can cancel unsent events", user=self.owner,
                prepare=self.grant_change, method="POST",
                expected=ExpectedResult(status_code=204, response_validators=self.event_cancelled)),
            RequestScenario(name="Calendar access without editing grants cannot cancel", user=self.owner,
                method="POST", expected=ExpectedResult(status_code=403, response_validators=self.event_active)),
            RequestScenario(name="Sent cancellation requires the original sending account", user=self.actor,
                prepare=self.mark_sent, method="POST",
                headers={"HX-Request": "true", "HX-Target": "calendar-event-create-form"},
                expected=ExpectedResult(response_validators=self.cancellation_failed)),
        ]

    def grant_change(self, scenario: RequestScenario) -> None:
        """Grant a regular staff user permission to edit and cancel the calendar event."""
        PolicyManager.create_policy(
            CalendarEvent, global_permissions=["view", "change"],
            field_permissions={"__all__": ["view", "change"]},
            row_permissions=[RowPolicyRuleContent(permissions=["view", "change"], conditions=[])],
        ).assign_user(self.owner)

    def mark_sent(self, scenario: RequestScenario) -> None:
        """Mark an invitation delivered without fabricating an accessible connected sender."""
        CalendarEvent.objects.filter(pk=self.timed.pk).update(invitation_sent_at=timezone.now())

    def event_cancelled(self, response: HttpResponse) -> bool:
        """Keep the event and its saved title while marking it cancelled and refreshing the calendar."""
        event = CalendarEvent.objects.get(pk=self.timed.pk)
        return event.cancelled and event.title == "Placed timed meeting" and response["HX-Refresh"] == "true"

    def event_active(self, response: HttpResponse) -> bool:
        """Preserve the event when cancellation was not authorized or could not be sent."""
        return not CalendarEvent.objects.get(pk=self.timed.pk).cancelled

    def cancellation_failed(self, response: HttpResponse) -> bool:
        """Render a recoverable error without marking an undelivered cancellation complete."""
        return self.event_active(response) and b"original sending account" in response.content
